//! Host management and ownership heartbeat lifecycle.
use std::{collections::HashMap, io::Write, path::Path, sync::Arc, time::Duration};

use clap::Subcommand;
use peer_network::{HeartbeatConfig, LeaderState, PairTicket, PeerNetwork, Role};
use reqwest::Method;
use serde_json::json;

use crate::{Result, client::Client};

#[derive(Debug, Subcommand)]
pub enum HostCmd {
    /// Pair this fresh host with a desktop before starting the service.
    Join {
        /// Pairing ticket generated by `bot host invite --role host` on your desktop.
        ticket: String,
    },
    /// Create a single-use invite and print its QR and confirmation code.
    Invite {
        /// Role for the invited device.
        #[arg(long, value_parser = ["phone", "desktop", "node", "host"])]
        role: String,
        /// How long the invite stays valid, in seconds (1 to 1800).
        #[arg(long)]
        ttl_secs: Option<u64>,
        /// Print only the pairing ticket (for scripts such as the one-command server setup).
        #[arg(long)]
        ticket_only: bool,
    },
    /// Show host ownership, peer status, and capabilities (JSON).
    Status,
    /// List paired devices (JSON).
    Devices,
    /// Revoke a paired device by its device key.
    Revoke {
        /// Paired device key (see `bot host devices`).
        key: String,
    },
    /// Stop automatic components and put this host in standby mode.
    Standby,
    /// Claim active host ownership for this installation.
    Activate {
        /// Activate using this installation's last local data even if another leader is unreachable.
        #[arg(long)]
        force: bool,
    },
    /// Configure screen-viewing and control permissions for a paired desktop (local only).
    ///
    /// The paired admin desktop (the owner's own) can already watch and drive
    /// this host's screen by default; use `--revoke` to switch it off or
    /// `--view-only` to allow watching only. Other devices need this grant.
    /// Run locally on the host; the setting persists across restarts.
    Screen {
        /// Paired device key from `bot host devices`.
        #[arg(required_unless_present = "all_desktops")]
        key: Option<String>,
        /// Apply to every paired device with the desktop role.
        #[arg(long, conflicts_with = "key")]
        all_desktops: bool,
        /// Allow watching only (no takeover or input).
        #[arg(long)]
        view_only: bool,
        /// Remove the screen grant instead of adding it.
        #[arg(long)]
        revoke: bool,
    },
    /// Grant or withdraw host administration permissions for a paired desktop (local only).
    ///
    /// Allows a paired desktop to send model keys, bots, and settings to this
    /// host. Run locally on the host. Needed once for desktops paired before
    /// host administration existed; new desktop invites grant it automatically.
    Admin {
        /// Paired device key from `bot host devices`.
        #[arg(required_unless_present = "all_desktops")]
        key: Option<String>,
        /// Apply to every paired device with the desktop role.
        #[arg(long, conflicts_with = "key")]
        all_desktops: bool,
        /// Withdraw host administration instead of granting it.
        #[arg(long)]
        revoke: bool,
    },
    /// Provision your own server over SSH: add, repair, upgrade, remove.
    #[command(flatten)]
    Provision(crate::host_provision::ProvisionCmd),
}

/// Request body of `POST /v1/host/invite`.
fn invite_body(role: &str, ttl_secs: Option<u64>) -> serde_json::Value {
    let mut body = json!({"role": role});
    if let Some(ttl) = ttl_secs {
        body["ttl_secs"] = json!(ttl);
    }
    body
}

/// Device keys a `host screen` command applies to.
async fn screen_targets(
    client: &Client,
    key: Option<&str>,
    all_desktops: bool,
) -> Result<Vec<String>> {
    let keys: Vec<String> = if all_desktops {
        let status = client.request(Method::GET, "/v1/host", None).await?;
        status["peers"]
            .as_array()
            .into_iter()
            .flatten()
            .filter(|p| p["role"] == "desktop")
            .filter_map(|p| p["key"].as_str().map(str::to_owned))
            .collect()
    } else {
        key.map(str::to_owned).into_iter().collect()
    };
    if keys.is_empty() {
        return Err(
            "no paired desktop found; run `bot host devices` to list paired devices".into(),
        );
    }
    if let Some(bad) = keys
        .iter()
        .find(|k| k.is_empty() || k.len() > 128 || !k.chars().all(|c| c.is_ascii_alphanumeric()))
    {
        return Err(format!(
            "invalid device key `{bad}`; run `bot host devices` to list valid device keys"
        )
        .into());
    }
    Ok(keys)
}

pub async fn join(data: &Path, ticket: &str) -> Result<()> {
    let ticket = PairTicket::parse(ticket).map_err(|e| {
        format!(
            "invalid pairing ticket: {e}; generate a new invite on your desktop with `bot host invite --role host`"
        )
    })?;
    if ticket.role != Role::Host {
        return Err(
            "`bot host join` requires a host invite ticket; create one on your desktop with `bot host invite --role host`"
                .into(),
        );
    }
    let mut host = daemon_api::host::HostConfig::load(data)?;
    if (data.join("host.toml").exists()
        && (host.mode != daemon_api::host::HostMode::Host
            || host.state != daemon_api::host::HostState::Fresh))
        || (!data.join("host.toml").exists() && data.join("bot.db").exists())
    {
        return Err(
            "`bot host join` requires a fresh installation with no existing data; use `bot host repair` or explicit handover for existing data"
                .into(),
        );
    }
    let (cfg, _) = crate::peer::config(data, true)?;
    let net = PeerNetwork::start(cfg, None).await?;
    let result = net.pair(&ticket).await;
    if let Ok(device) = &result
        && device.role != Role::Desktop
    {
        let _ = net.revoke(&ticket.addr.id);
    }
    net.shutdown().await;
    let device = result?;
    if device.role != Role::Desktop {
        return Err(
            "host invite must originate from a desktop; create the invite on your desktop with `bot host invite --role host`"
                .into(),
        );
    }
    host.mode = daemon_api::host::HostMode::Host;
    host.state = daemon_api::host::HostState::Fresh;
    host.leader = None;
    host.save(data)?;
    println!(
        "Paired desktop {}. Next: start the host daemon with `bot serve --host`.",
        device.id
    );
    Ok(())
}

#[allow(clippy::too_many_lines)] // one dispatcher over the host subcommands
pub async fn run(
    client: &Client,
    action: &HostCmd,
    json_output: bool,
    out: &mut dyn Write,
    data: &Path,
) -> Result<()> {
    if let HostCmd::Screen {
        key,
        all_desktops,
        view_only,
        revoke,
    } = action
    {
        for key in screen_targets(client, key.as_deref(), *all_desktops).await? {
            let (view, input) = (!revoke, !revoke && !view_only);
            client
                .request(
                    Method::PUT,
                    &format!("/v1/view/privileges/{key}"),
                    Some(json!({"view": view, "input": input})),
                )
                .await?;
            writeln!(
                out,
                "{key}: screen view={view} input={input} (kept across restarts)"
            )?;
        }
        return Ok(());
    }
    if let HostCmd::Admin {
        key,
        all_desktops,
        revoke,
    } = action
    {
        // The owner key of THIS data dir (a file only the host's own account
        // reads), not the general API token.
        let owner = daemon_api::read_owner_key(data).map_err(|_| {
            "no owner key found in this data directory; run `bot host admin` locally on the host as the service user after starting `bot serve --host` once"
        })?;
        for key in screen_targets(client, key.as_deref(), *all_desktops).await? {
            client
                .request_owner(
                    Method::PUT,
                    &format!("/v1/host/devices/{key}/admin"),
                    Some(json!({"enabled": !revoke})),
                    &owner,
                )
                .await?;
            if *revoke {
                writeln!(out, "{key}: host administration withdrawn")?;
            } else {
                writeln!(
                    out,
                    "{key}: may now send model keys, bots and settings to this host"
                )?;
            }
        }
        return Ok(());
    }
    let (method, path, body) = match action {
        HostCmd::Status | HostCmd::Devices => (Method::GET, "/v1/host".into(), None),
        HostCmd::Invite { role, ttl_secs, .. } => (
            Method::POST,
            "/v1/host/invite".into(),
            Some(invite_body(role, *ttl_secs)),
        ),
        HostCmd::Revoke { key } => {
            let key = peer_network::key_from_string(key).map_err(|e| {
                format!(
                    "invalid device key `{key}`: {e}; run `bot host devices` to list paired device keys"
                )
            })?;
            (Method::DELETE, format!("/v1/host/devices/{key}"), None)
        }
        HostCmd::Standby => (Method::POST, "/v1/host/standby".into(), None),
        HostCmd::Activate { force } => (
            Method::POST,
            "/v1/host/activate".into(),
            Some(json!({"force": force})),
        ),
        HostCmd::Join { .. }
        | HostCmd::Screen { .. }
        | HostCmd::Admin { .. }
        | HostCmd::Provision(_) => {
            return Err("this command is local only".into());
        }
    };
    if matches!(action, HostCmd::Activate { force: true }) {
        eprintln!(
            "Forced activation uses this installation's last local data; newer changes on the other leader may be missing, and missed schedules can duplicate actions already run there."
        );
    }
    // A desktop invite asks for host administration with the owner key; without
    // one (no key file) the invite is an ordinary one.
    let owner = matches!(action, HostCmd::Invite { .. })
        .then(|| daemon_api::read_owner_key(data).ok())
        .flatten();
    let mut response = match owner {
        Some(key) => client.request_owner(method, &path, body, &key).await?,
        None => client.request(method, &path, body).await?,
    };
    if matches!(action, HostCmd::Devices) {
        response = response["peers"].clone();
    }
    if let HostCmd::Invite {
        ticket_only: true, ..
    } = action
    {
        let invite: daemon_api::host::HostInvite = serde_json::from_value(response)?;
        writeln!(out, "{}", invite.ticket)?;
    } else if !json_output && matches!(action, HostCmd::Invite { .. }) {
        let invite: daemon_api::host::HostInvite = serde_json::from_value(response)?;
        let qr = qrcode::QrCode::new(invite.ticket.as_bytes())?;
        writeln!(
            out,
            "{}",
            qr.render::<qrcode::render::unicode::Dense1x2>().build()
        )?;
        writeln!(out, "Code: {}\n{}", invite.code, invite.ticket)?;
    } else {
        writeln!(out, "{}", serde_json::to_string_pretty(&response)?)?;
    }
    Ok(())
}

/// Keep links to daemon peers, publish metadata and apply authenticated events.
pub fn watch_peers(state: &daemon_api::AppState, net: PeerNetwork) {
    watch_peers_with_config(state, net, HeartbeatConfig::default());
}

fn watch_peers_with_config(
    state: &daemon_api::AppState,
    net: PeerNetwork,
    heartbeat: HeartbeatConfig,
) {
    state.leader().set_network(net.clone());
    let weak = state.downgrade();
    let mut events = net.subscribe();
    let shutdown = state.shutdown_token();
    tokio::spawn(async move {
        let mut links = HashMap::new();
        let mut tick = tokio::time::interval(Duration::from_secs(2));
        loop {
            tokio::select! {
                () = shutdown.cancelled() => break,
                _ = tick.tick() => {
                    let devices = net.devices();
                    links.retain(|key, task: &mut tokio::task::JoinHandle<()>| {
                        let keep = devices.iter().any(|d| &d.id == key) && !task.is_finished();
                        if !keep { task.abort(); }
                        keep
                    });
                    for device in devices.iter().filter(|d| matches!(d.role, Role::Host | Role::Desktop)) {
                        if !links.contains_key(&device.id) && let Ok(key) = peer_network::key_from_string(&device.id) {
                            links.insert(device.id.clone(), net.spawn_heartbeat(key, heartbeat, Arc::new(|_| {})));
                        }
                    }
                }
                event = events.recv() => {
                    let event = match event {
                        Ok(event) => event,
                        Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
                        Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
                    };
                    if !net.device(&event.peer).is_some_and(|d| matches!(d.role, Role::Host | Role::Desktop)) { continue; }
                    let Some(state) = weak.upgrade() else { break; };
                    if event.event.kind == "host_conflict" {
                        // Ignore event.leader: this frame echoes the receiver.
                        // observe_conflict reads the sender's heartbeat cache.
                        if let Err(e) = state
                            .leader()
                            .observe_conflict(&peer_network::key_to_string(&event.peer))
                            .await
                        {
                            support_logs::tracing::warn!(target: "praxi_support", reason = "component_warning", "host conflict: {e}");
                        }
                        continue;
                    }
                    if event.event.kind != "heartbeat" { continue; }
                    if let Some(info) = event.leader {
                        let local = state.leader().config();
                        let conflict = local.state == daemon_api::host::HostState::Active && info.state == LeaderState::Active && info.epoch == local.epoch;
                        if let Err(e) = state.leader().observe(&event.peer.to_string(), info).await { support_logs::tracing::warn!(target: "praxi_support", reason = "component_warning", "host leadership: {e}"); }
                        if conflict {
                            // Echo the heartbeat we just applied. The receiver ignores
                            // this field and reads our state from its heartbeat cache.
                            let message = peer_network::proto::Event { leader: Some(info), kind: "host_conflict".into(), ts_ms: u64::try_from(storage::now_ms()).unwrap_or(0), data: json!({"reason":"equal_epoch"}) };
                            let _ = tokio::time::timeout(Duration::from_secs(2), async {
                                let conn = net.connect(&event.peer, peer_network::ALPN_EVENTS).await?;
                                let mut send = conn.open_uni().await.map_err(|e| peer_network::PeerError::Connection(e.to_string()))?;
                                peer_network::proto::write_frame(&mut send, &serde_json::to_vec(&message).expect("plain event"), peer_network::proto::MAX_FRAME).await?;
                                let _ = send.finish();
                                let _ = send.stopped().await;
                                Ok::<_, peer_network::PeerError>(())
                            }).await;
                        }
                    }
                }
            }
        }
        if let Some(state) = weak.upgrade() {
            state.leader().detach_network();
        }
        for (_, task) in links {
            task.abort();
        }
    });
}

#[cfg(test)]
mod tests {
    use super::*;
    use daemon_api::host::{HostConfig, HostState};
    use peer_network::{PeerConfig, RelayConfig};

    #[test]
    fn invite_options_reach_the_request_and_default_to_no_ttl() {
        assert_eq!(
            invite_body("desktop", Some(1800)),
            json!({"role": "desktop", "ttl_secs": 1800})
        );
        assert_eq!(invite_body("host", None), json!({"role": "host"}));
    }

    async fn daemon(data: &Path, epoch: u64) -> (daemon_api::AppState, PeerNetwork) {
        HostConfig {
            epoch,
            ..HostConfig::default()
        }
        .save(data)
        .unwrap();
        let storage = Arc::new(storage::Storage::open(data).unwrap());
        let agent = agent_core::AgentLoop::new(
            storage.clone(),
            tool_registry::ToolRegistry::new(),
            agent_core::Providers::single(Arc::new(daemon_api::fake::FakeProvider)),
            agent_core::LoopConfig::default(),
        );
        let state =
            daemon_api::AppState::new(agent, storage, daemon_api::DaemonConfig::new("test-token"))
                .unwrap();
        let mut config = PeerConfig::new(data.join("peer"));
        config.relay = RelayConfig::Disabled;
        config.bind_addr = Some("127.0.0.1:0".parse().unwrap());
        let net = PeerNetwork::start(config, None).await.unwrap();
        (state, net)
    }

    #[tokio::test]
    async fn authenticated_heartbeat_demotes_lower_epoch_and_equal_epoch_stops_both() {
        for epoch in [0, 3] {
            let a_dir = tempfile::tempdir().unwrap();
            let b_dir = tempfile::tempdir().unwrap();
            let (a, a_net) = daemon(a_dir.path(), 0).await;
            let (b, b_net) = daemon(b_dir.path(), epoch).await;
            let invite = a_net.create_invite(Role::Desktop).await;
            b_net
                .pair(&PairTicket::parse(&invite.ticket).unwrap())
                .await
                .unwrap();
            let heartbeat = HeartbeatConfig {
                interval: Duration::from_millis(50),
                initial_backoff: Duration::from_millis(10),
                max_backoff: Duration::from_millis(100),
                connect_timeout: Duration::from_secs(2),
            };
            let mut a_events = a.leader().subscribe();
            let mut b_events = b.leader().subscribe();
            watch_peers_with_config(&a, a_net.clone(), heartbeat);
            watch_peers_with_config(&b, b_net.clone(), heartbeat);
            tokio::time::timeout(Duration::from_secs(12), async {
                while a.leader().config().state != HostState::Standby
                    || (epoch == 0 && b.leader().config().state != HostState::Standby)
                {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
            })
            .await
            .expect("heartbeat ownership policy converges");
            if epoch == 0 {
                assert!(matches!(
                    a_events.recv().await.unwrap(),
                    daemon_api::host::HostEvent::HostStateChanged(_)
                ));
                assert!(matches!(
                    a_events.recv().await.unwrap(),
                    daemon_api::host::HostEvent::HostConflict(_)
                ));
                assert!(matches!(
                    b_events.recv().await.unwrap(),
                    daemon_api::host::HostEvent::HostStateChanged(_)
                ));
                assert!(matches!(
                    b_events.recv().await.unwrap(),
                    daemon_api::host::HostEvent::HostConflict(_)
                ));
            } else {
                assert_eq!(b.leader().config().state, HostState::Active);
            }
            a.shutdown_token().cancel();
            b.shutdown_token().cancel();
            a_net.shutdown().await;
            b_net.shutdown().await;
        }
    }

    struct StartupCounter(Arc<std::sync::atomic::AtomicUsize>);
    #[async_trait::async_trait]
    impl daemon_api::ChannelControl for StartupCounter {
        fn start(&self) {
            self.0.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        }
        async fn stop(&self) {}
        fn info(&self) -> daemon_api::dto::ChannelDto {
            panic!("unused")
        }
        fn create_pair_code(&self) -> std::result::Result<daemon_api::dto::PairCodeDto, String> {
            panic!("unused")
        }
    }

    #[tokio::test]
    async fn restarted_stale_owner_checks_real_peers_before_starting_components() {
        let a_dir = tempfile::tempdir().unwrap();
        let b_dir = tempfile::tempdir().unwrap();
        let (a, a_net) = daemon(a_dir.path(), 0).await;
        let (b, b_net) = daemon(b_dir.path(), 4).await;
        let invite = a_net.create_invite(Role::Desktop).await;
        b_net
            .pair(&PairTicket::parse(&invite.ticket).unwrap())
            .await
            .unwrap();
        // Reopen the same identity, pairing store and stale active host.toml.
        a.shutdown_token().cancel();
        a_net.shutdown().await;
        drop(a_net);
        drop(a);
        let (a, a_net) = daemon(a_dir.path(), 0).await;
        let starts = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        a.add_channel(Arc::new(StartupCounter(starts.clone())));
        // Persisted active configuration is loaded before the transport has a verdict.
        a.leader().set_network(a_net.clone());
        let started = a.clone();
        let startup = tokio::spawn(async move { started.leader().start().await });
        tokio::time::sleep(Duration::from_millis(100)).await;
        assert_eq!(starts.load(std::sync::atomic::Ordering::SeqCst), 0);
        assert!(!startup.is_finished());
        let heartbeat = HeartbeatConfig {
            interval: Duration::from_millis(50),
            initial_backoff: Duration::from_millis(10),
            max_backoff: Duration::from_millis(100),
            connect_timeout: Duration::from_secs(2),
        };
        watch_peers_with_config(&a, a_net.clone(), heartbeat);
        watch_peers_with_config(&b, b_net.clone(), heartbeat);
        tokio::time::timeout(Duration::from_secs(12), startup)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        assert_eq!(a.leader().config().state, HostState::Standby);
        assert_eq!(starts.load(std::sync::atomic::Ordering::SeqCst), 0);
        a.shutdown_token().cancel();
        b.shutdown_token().cancel();
        a_net.shutdown().await;
        b_net.shutdown().await;
    }

    #[tokio::test]
    async fn host_join_records_desktop_and_preserves_fresh_mode() {
        let desktop_dir = tempfile::tempdir().unwrap();
        let host_dir = tempfile::tempdir().unwrap();
        let (_, desktop) = daemon(desktop_dir.path(), 0).await;
        std::fs::write(
            host_dir.path().join("config.toml"),
            "[peer]\nrelay='none'\n",
        )
        .unwrap();
        let invite = desktop.create_invite(Role::Host).await;
        join(host_dir.path(), &invite.ticket).await.unwrap();
        let config = HostConfig::load(host_dir.path()).unwrap();
        assert_eq!(config.mode, daemon_api::host::HostMode::Host);
        assert_eq!(config.state, HostState::Fresh);
        let (peer_config, _) = crate::peer::config(host_dir.path(), true).unwrap();
        let net = PeerNetwork::start(peer_config, None).await.unwrap();
        assert_eq!(net.devices().len(), 1);
        assert_eq!(net.devices()[0].role, Role::Desktop);
        assert_eq!(desktop.devices()[0].role, Role::Host);
        net.shutdown().await;
        desktop.shutdown().await;
    }

    async fn push_event(
        from: &PeerNetwork,
        to: &PeerNetwork,
        leader: Option<peer_network::LeaderInfo>,
        kind: &str,
    ) {
        let message = peer_network::proto::Event {
            leader,
            kind: kind.into(),
            ts_ms: 1,
            data: json!({}),
        };
        let conn = tokio::time::timeout(
            Duration::from_secs(3),
            from.connect(&to.id(), peer_network::ALPN_EVENTS),
        )
        .await
        .expect("event connect")
        .unwrap();
        let mut send = conn.open_uni().await.unwrap();
        peer_network::proto::write_frame(
            &mut send,
            &serde_json::to_vec(&message).unwrap(),
            peer_network::proto::MAX_FRAME,
        )
        .await
        .unwrap();
        let _ = send.finish();
        let _ = send.stopped().await;
    }

    #[tokio::test]
    async fn host_conflict_ignores_echoed_leader_and_uses_sender_heartbeat_cache() {
        // Production puts the receiver's own heartbeat into `leader`. These
        // cases disagree with the sender cache, so trusting the frame fails.
        for (cached, echoed, demote) in [
            (LeaderState::Standby, LeaderState::Active, false),
            (LeaderState::Active, LeaderState::Standby, true),
        ] {
            let a_dir = tempfile::tempdir().unwrap();
            let b_dir = tempfile::tempdir().unwrap();
            let (a, a_net) = daemon(a_dir.path(), 4).await;
            let (b, b_net) = daemon(b_dir.path(), 4).await;
            let invite = a_net.create_invite(Role::Desktop).await;
            b_net
                .pair(&PairTicket::parse(&invite.ticket).unwrap())
                .await
                .unwrap();
            let cached_info = peer_network::LeaderInfo {
                epoch: 4,
                state: cached,
            };
            a_net.set_leader_info(Some(cached_info));
            push_event(&a_net, &b_net, Some(cached_info), "heartbeat").await;
            tokio::time::timeout(Duration::from_secs(2), async {
                while b_net.peer_leader(&a_net.id()) != Some(cached_info) {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
            })
            .await
            .expect("sender heartbeat cached");
            // Let that frame finish with no watcher subscribed.
            tokio::time::sleep(Duration::from_millis(100)).await;
            let mut events = b.leader().subscribe();
            watch_peers_with_config(
                &b,
                b_net.clone(),
                HeartbeatConfig {
                    interval: Duration::from_secs(60),
                    initial_backoff: Duration::from_secs(60),
                    max_backoff: Duration::from_secs(60),
                    connect_timeout: Duration::from_secs(2),
                },
            );
            tokio::time::sleep(Duration::from_millis(30)).await;
            push_event(
                &a_net,
                &b_net,
                Some(peer_network::LeaderInfo {
                    epoch: 4,
                    state: echoed,
                }),
                "host_conflict",
            )
            .await;
            if demote {
                tokio::time::timeout(Duration::from_secs(3), async {
                    while b.leader().config().state != HostState::Standby {
                        tokio::time::sleep(Duration::from_millis(10)).await;
                    }
                })
                .await
                .expect("cached active sender demotes");
            } else {
                let changed = tokio::time::timeout(Duration::from_millis(800), events.recv()).await;
                assert!(
                    changed.is_err(),
                    "echoed leader must not demote when the sender cache is {cached:?}"
                );
                assert_eq!(b.leader().config().state, HostState::Active);
            }
            a.shutdown_token().cancel();
            b.shutdown_token().cancel();
            a_net.shutdown().await;
            b_net.shutdown().await;
        }
    }
}
